/// The tithi in effect at `unix`.
pub fn tithi_at(&self, unix: i64) -> Option<TithiSpan> {
    let i = self.times.partition_point(|&t| t <= unix);
    (i > 0 && i < self.times.len()).then(|| self.span(i - 1))
}

